<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, shallowRef, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { registryRequest, type ClusterPage } from '../api/registry'
import { kafkaList, type Topic } from '../api/kafkaops'
import { readLineage, observedTime, evidenceLabel, kindLabel, resourcePath, type Direction, type Lineage, type LineageNode, type LineageEdge } from '../api/topic-lineage'
import TopicLineageCanvas from '../components/TopicLineageCanvas.vue'
const route=useRoute(),router=useRouter()
const cluster=ref(''),topic=ref(''),direction=ref<Direction>('both'),depth=ref(2)
const clusters=shallowRef<ClusterPage['items']>([]),topics=ref<string[]>([]),topicTruncated=ref(false),clusterTruncated=ref(false),catalogError=ref('')
const data=shallowRef<Lineage>(),selectedNode=shallowRef<LineageNode>(),selectedEdge=shallowRef<LineageEdge>(),busy=ref(false),error=ref('')
let request:InstanceType<typeof globalThis.AbortController>|undefined,epoch=0,catalogEpoch=0,timer:ReturnType<typeof globalThis.setTimeout>|undefined
const selectedPath=computed(()=>selectedNode.value?resourcePath(selectedNode.value):undefined)
const nodeName=(id:string)=>data.value?.nodes.find(n=>n.id===id)?.label??'资源未知'
async function loadTopics(){const token=++catalogEpoch;topics.value=[];topicTruncated.value=false;catalogError.value='';if(!cluster.value)return;try{const names:string[]=[];let total=0;for(let page=1;page<=100;page++){const result=await kafkaList<Topic>(cluster.value,'topics',{page,pageSize:100,query:topic.value});if(token!==catalogEpoch)return;names.push(...result.items.map(n=>n.name));total=result.total;if(names.length>=total||!result.items.length)break}if(token===catalogEpoch){topics.value=[...new Set(names)];topicTruncated.value=names.length<total}}catch{if(token===catalogEpoch)catalogError.value='Topic 列表暂不可用，可输入完整名称查询'}}
async function query(){if(!cluster.value||!topic.value.trim())return;const previous=route.fullPath;await router.push({path:'/topic-lineage',query:{cluster_id:cluster.value,topic:topic.value.trim(),depth:String(depth.value),direction:direction.value}});if(previous===route.fullPath)void load()}
async function load(){globalThis.clearTimeout(timer);request?.abort();const token=++epoch;data.value=undefined;selectedNode.value=undefined;selectedEdge.value=undefined;error.value='';if(!cluster.value||!topic.value.trim()){busy.value=false;return}busy.value=true;request=new globalThis.AbortController();timer=globalThis.setTimeout(()=>request?.abort(),20000);try{const result=await readLineage(cluster.value,topic.value.trim(),depth.value,direction.value,request.signal);if(token===epoch)data.value=result}catch(e){if(token===epoch)error.value=(e as Error).name==='AbortError'?'查询超时或已取消，请重试':(e as Error).message}finally{if(token===epoch){busy.value=false;globalThis.clearTimeout(timer)}}}
function syncQuery(){cluster.value=String(route.query.cluster_id??'');topic.value=String(route.query.topic??'');const d=Number(route.query.depth??2);depth.value=[1,2,3,4].includes(d)?d:2;direction.value=['upstream','downstream','both'].includes(String(route.query.direction))?route.query.direction as Direction:'both';void load()}
watch(()=>route.fullPath,syncQuery,{immediate:true})
watch(cluster,()=>void loadTopics())
onMounted(async()=>{void loadTopics();try{const result=await registryRequest<ClusterPage>('/kafka/clusters?page=1&page_size=100');clusters.value=result.items;clusterTruncated.value=result.total>result.items.length}catch{catalogError.value='集群列表加载失败，请刷新重试'}})
onBeforeUnmount(()=>{++epoch;++catalogEpoch;request?.abort();globalThis.clearTimeout(timer)})
</script>
<template>
  <section class="lineage-page registry">
    <header class="page-header"><div><h1>Topic 全链路</h1><p>从一个 Topic 追踪同步配置、消费证据与应用登记。</p></div><router-link to="/applications">登记应用关系</router-link></header>
    <form class="lineage-query panel" @submit.prevent="query"><label>集群<select v-model="cluster" aria-label="集群" required><option value="" disabled>选择集群</option><option v-for="item in clusters" :key="item.id" :value="item.id">{{ item.display_name }}</option></select></label><label class="topic-input">Topic<input v-model="topic" aria-label="Topic" list="lineage-topics" placeholder="搜索或输入完整 Topic 名称" required @change="loadTopics"><datalist id="lineage-topics"><option v-for="name in topics" :key="name" :value="name" /></datalist></label><label>方向<select v-model="direction" aria-label="方向"><option value="both">上下游</option><option value="upstream">上游</option><option value="downstream">下游</option></select></label><label>深度<select v-model.number="depth" aria-label="深度"><option v-for="value in 4" :key="value" :value="value">{{ value }} 段</option></select></label><button class="primary" type="submit" :disabled="busy || !cluster || !topic.trim()">{{ busy?'查询中…':'查看链路' }}</button></form>
    <p v-if="catalogError" role="status">{{ catalogError }}</p><p v-if="topicTruncated || clusterTruncated" role="status">候选列表已截断（Topic 最多 10000 个）；可输入完整 Topic 名称查询。</p><p v-if="error" role="alert">{{ error }} <button @click="load">重试查询</button></p><p v-if="busy" role="status">正在读取 Topic 关系…</p>
    <template v-if="data">
      <div class="lineage-meta"><span>{{ data.nodes.length }} 个节点 · {{ data.edges.length }} 条关系 · 采集结果最多缓存 1 分钟</span><span>采集时间 {{ observedTime(data.observed_at) }}</span></div><p v-if="data.truncated" class="bounds" role="status">结果已达到查询边界，部分关系未展开。可缩小深度或从相邻 Topic 继续查询。</p><details v-if="data.issues.length" class="lineage-issues"><summary>{{ data.issues.length }} 项局部问题，已展示可读取的关系</summary><ul><li v-for="(issue,index) in data.issues" :key="index">{{ issue.message }}</li></ul></details>
      <div class="lineage-workspace" :class="{'has-selection': selectedNode || selectedEdge}"><TopicLineageCanvas :data="data" @select-node="selectedNode=$event;selectedEdge=undefined" @select-edge="selectedEdge=$event;selectedNode=undefined" /><aside v-if="selectedNode || selectedEdge" class="lineage-detail panel" aria-label="链路详情"><button class="detail-close" aria-label="关闭链路详情" @click="selectedNode=undefined;selectedEdge=undefined">关闭</button><template v-if="selectedNode"><h2>{{ kindLabel(selectedNode.kind) }}</h2><h3>{{ selectedNode.label }}</h3><dl><template v-if="selectedNode.cluster_name"><dt>集群</dt><dd>{{ selectedNode.cluster_name }}</dd></template><template v-if="selectedNode.owner"><dt>负责人</dt><dd>{{ selectedNode.owner }}</dd></template><template v-if="selectedNode.location"><dt>部署位置</dt><dd>{{ selectedNode.location }}</dd></template><dt>证据</dt><dd>{{ evidenceLabel(selectedNode.evidence) }}</dd><template v-if="selectedNode.kind==='topic'"><dt>Topic 存在性</dt><dd>{{ selectedNode.exists===true?'已读取到 Topic（不代表复制已验证）':selectedNode.exists===false?'未读取到 Topic':'未知' }}</dd></template><dt>采集时间</dt><dd>{{ observedTime(selectedNode.observed_at) }}</dd></dl><router-link v-if="selectedPath" :to="selectedPath">查看资源详情</router-link><button v-if="selectedNode.kind==='topic' && selectedNode.cluster_id" @click="router.push({path:'/topic-lineage',query:{cluster_id:selectedNode.cluster_id,topic:selectedNode.topic??selectedNode.label,depth:String(depth),direction}})">以此 Topic 为根</button></template><template v-else-if="selectedEdge"><h2>关系详情</h2><h3>{{ nodeName(selectedEdge.source) }} → {{ nodeName(selectedEdge.target) }}</h3><dl><template v-if="selectedEdge.account"><dt>Kafka 账号</dt><dd>{{ selectedEdge.account }}</dd></template><template v-if="selectedEdge.client_id"><dt>Client ID</dt><dd>{{ selectedEdge.client_id }}</dd></template><dt>证据来源</dt><dd>{{ evidenceLabel(selectedEdge.evidence) }}</dd><dt>采集时间</dt><dd>{{ observedTime(selectedEdge.observed_at) }}</dd><template v-if="selectedEdge.policy"><dt>命名策略</dt><dd>{{ selectedEdge.policy }}</dd></template><template v-if="selectedEdge.rule"><dt>匹配规则</dt><dd>{{ selectedEdge.rule }}</dd></template></dl></template><template v-else><h2>关系证据</h2><p>点击节点或连线查看来源与采集时间。</p><p>配置同步与目标存在性不能证明消息复制成功。</p></template></aside></div>
      <div class="evidence-legend" aria-label="证据图例"><span>实线：实际观测</span><span>虚线：配置 / 人工 / 历史 / 未知</span></div><p v-if="!data.edges.length" class="lineage-empty">暂未发现可展示的关系。Kafka 元数据无法自动识别生产应用；应用关系需人工登记，消费证据取决于可读取的组信息。</p><details class="lineage-accessible"><summary>节点与关系列表</summary><div><button v-for="node in data.nodes" :key="node.id" :data-lineage-node="node.id" @click="selectedNode=node;selectedEdge=undefined">{{ kindLabel(node.kind) }}：{{ node.label }}{{ node.cluster_name?'（'+node.cluster_name+'）':'' }}</button></div><div><button v-for="edge in data.edges" :key="edge.id" :data-lineage-edge="edge.id" @click="selectedEdge=edge;selectedNode=undefined">{{ nodeName(edge.source) }} → {{ nodeName(edge.target) }}：{{ evidenceLabel(edge.evidence) }}{{ edge.account?' · 账号：'+edge.account:'' }}</button></div></details>
    </template><div v-else-if="!busy && !error" class="panel lineage-empty">选择集群和 Topic，查看其上下游关系。</div>
  </section>
</template>
<style scoped>.page-header h1{margin-bottom:8px}.page-header p,.lineage-detail p{color:#64748b;font-size:13px}.lineage-query{display:flex;align-items:end;gap:14px;padding:18px;margin-bottom:16px;flex-wrap:wrap}.lineage-query label{display:flex;flex-direction:column;gap:8px;font-size:12px;color:#526174}.lineage-query select,.lineage-query input{height:38px;border:1px solid #ccd7e5;border-radius:5px;padding:0 10px;background:#fff;color:#25304a;min-width:100px}.lineage-query .topic-input{flex:1;min-width:200px}.lineage-query button{height:38px}.lineage-meta{display:flex;gap:20px;justify-content:space-between;font-size:12px;color:#64748b;margin:16px 0}.lineage-workspace{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}.lineage-workspace.has-selection{grid-template-columns:minmax(0,1fr) 260px}.detail-close{float:right}.lineage-detail{padding:20px;overflow-wrap:anywhere}.lineage-detail h2{font-size:14px;margin:0 0 18px}.lineage-detail h3{font-size:16px}.lineage-detail dt{font-size:12px;color:#64748b;margin-top:18px}.lineage-detail dd{font-size:13px;margin:6px 0}.lineage-detail button{margin-top:14px}.lineage-detail a{font-size:13px}.evidence-legend{display:flex;gap:20px;font-size:12px;color:#64748b;margin:14px 0}.bounds,.lineage-issues{background:#fff7e9;padding:12px;color:#805e2d;font-size:13px;margin-bottom:14px}.lineage-issues summary,.lineage-accessible summary{cursor:pointer}.lineage-empty{padding:22px;color:#64748b;font-size:13px}.lineage-accessible{margin-top:16px;font-size:12px;color:#64748b}.lineage-accessible button{margin:8px 8px 0 0;font-size:12px}@media(max-width:1000px){.lineage-workspace,.lineage-workspace.has-selection{grid-template-columns:1fr}.lineage-query label{flex:1}.lineage-meta{flex-wrap:wrap}}
</style>
